const incoming = $input.first().json;
const headers = incoming.headers ?? {};
const body = incoming.body ?? {};
const signature = String(headers['x-staging-signature'] ?? '');
const expectedSignature = String($env.N8N_STAGING_SIGNATURE ?? '');
const reply = (statusCode, responseBody) => [{ json: { statusCode, responseBody } }];

if (!expectedSignature || signature !== expectedSignature) {
  return reply(401, { accepted: false, code: 'authentication_failed' });
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return reply(400, { accepted: false, code: 'invalid_request', detail: 'Request body must be a JSON object.' });
}

const allowedKeys = new Set(['request_id', 'message', 'customer_email', 'customer_url']);
const unexpectedKeys = Object.keys(body).filter((key) => !allowedKeys.has(key));
if (unexpectedKeys.length > 0) {
  return reply(400, {
    accepted: false,
    code: 'invalid_request',
    detail: `Unexpected fields: ${unexpectedKeys.join(', ')}`,
  });
}

const requestId = String(body.request_id ?? '').trim();
const message = String(body.message ?? '').trim();
const customerEmail = String(body.customer_email ?? '').trim().toLowerCase();
const rawCustomerUrl = String(body.customer_url ?? '').trim();

if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]{2,63}$/.test(requestId)) {
  return reply(400, { accepted: false, code: 'invalid_request', detail: 'request_id must be a short stable identifier.' });
}
if (!message || message.length > 2000) {
  return reply(400, { accepted: false, code: 'invalid_request', detail: 'message must contain 1 to 2000 characters.' });
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)) {
  return reply(400, { accepted: false, code: 'invalid_request', detail: 'customer_email is invalid.' });
}
if (!/^https:\/\/support\.example\.org\/[^\s\\]*$/i.test(rawCustomerUrl)) {
  return reply(400, { accepted: false, code: 'invalid_request', detail: 'customer_url is outside the staging allowlist.' });
}

const state = $getWorkflowStaticData('global');
state.requests ??= {};
state.actionsExecuted = Number.isInteger(state.actionsExecuted) ? state.actionsExecuted : 0;

if (state.requests[requestId]) {
  return reply(200, {
    ...state.requests[requestId],
    actions_executed: state.actionsExecuted,
    duplicate: true,
  });
}

const riskFlags = /ignore\s+(all\s+)?previous|system\s+prompt|bypass\s+approval/i.test(message)
  ? ['instruction_override_attempt']
  : [];
const record = {
  accepted: true,
  status: 'pending_approval',
  actions_executed: state.actionsExecuted,
  request_id: requestId,
  duplicate: false,
  risk_flags: riskFlags,
};
state.requests[requestId] = record;

return reply(202, record);

const incoming = $input.first().json;
const headers = incoming.headers ?? {};
const body = incoming.body ?? {};
const signature = String(headers['x-staging-signature'] ?? '');
const expectedSignature = String($env.N8N_STAGING_SIGNATURE ?? '');
const expectedApprovalToken = String($env.N8N_STAGING_APPROVAL_TOKEN ?? '');
const reply = (statusCode, responseBody) => [{ json: { statusCode, responseBody } }];

if (!expectedSignature || signature !== expectedSignature) {
  return reply(401, { accepted: false, code: 'authentication_failed' });
}

const state = $getWorkflowStaticData('global');
state.requests ??= {};
state.actionsExecuted = Number.isInteger(state.actionsExecuted) ? state.actionsExecuted : 0;

if (!expectedApprovalToken || String(body.approval_token ?? '') !== expectedApprovalToken) {
  return reply(403, {
    accepted: false,
    code: 'approval_required',
    actions_executed: state.actionsExecuted,
  });
}

const requestId = String(body.request_id ?? '').trim();
if (!state.requests[requestId]) {
  return reply(404, {
    accepted: false,
    code: 'request_not_found',
    actions_executed: state.actionsExecuted,
  });
}

if (!state.requests[requestId].approved) {
  state.requests[requestId].approved = true;
  state.actionsExecuted += 1;
}

return reply(200, {
  accepted: true,
  status: 'simulated_action_recorded',
  actions_executed: state.actionsExecuted,
});

const incoming = $input.first().json;
const headers = incoming.headers ?? {};
const signature = String(headers['x-staging-signature'] ?? '');
const expectedSignature = String($env.N8N_STAGING_SIGNATURE ?? '');
const reply = (statusCode, responseBody) => [{ json: { statusCode, responseBody } }];

if (!expectedSignature || signature !== expectedSignature) {
  return reply(401, { accepted: false, code: 'authentication_failed' });
}

const state = $getWorkflowStaticData('global');
state.requests ??= {};
state.actionsExecuted = Number.isInteger(state.actionsExecuted) ? state.actionsExecuted : 0;

return reply(200, {
  actions_executed: state.actionsExecuted,
  accepted_requests: Object.keys(state.requests).length,
});

return [{
  json: {
    statusCode: 405,
    responseBody: { accepted: false, code: 'method_not_allowed' },
  },
}];
